package binding

import (
	"errors"
	"fmt"

	"fyne.io/fyne/v2/storage"
)

// NewSprintf creates a String binding that formats multiple data bindings using fmt.Sprintf.
// When any source binding changes, the formatted string is automatically updated.
// Set() parses the string back using fmt.Sscanf to update source bindings.
//
// Since: 2.5
func NewSprintf(format string, bindings ...DataItem) String {
	if len(bindings) == 0 {
		return NewString()
	}

	s := &sprintfBinding{
		format:   format,
		bindings: bindings,
	}

	// Listen to all source bindings
	for _, b := range bindings {
		b.AddListener(s)
	}

	return s
}

// StringToStringWithFormat wraps a String binding with a format string.
// If the format is "%s", returns the original binding unchanged.
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

type sprintfBinding struct {
	base
	format   string
	bindings []DataItem
	lastErr  error
}

func (s *sprintfBinding) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	if s.lastErr != nil {
		return "", s.lastErr
	}

	values, err := s.getValues()
	if err != nil {
		return "", err
	}

	return fmt.Sprintf(s.format, values...), nil
}

func (s *sprintfBinding) Set(val string) error {
	s.lock.Lock()
	defer s.lock.Unlock()

	values, err := s.getValues()
	if err != nil {
		return err
	}

	// Parse the string back using Sscanf
	newValues := make([]interface{}, len(values))
	for i := range values {
		newValues[i] = new(interface{})
	}

	n, err := fmt.Sscanf(val, s.format, newValues...)
	if err != nil && n == 0 {
		return err
	}

	// Set each binding with parsed value
	for i, b := range s.bindings {
		if i >= len(newValues) {
			break
		}

		val := newValues[i]
		if ptr, ok := val.(*interface{}); ok {
			val = *ptr
		}

		if err := s.setBinding(b, val); err != nil {
			return err
		}
	}

	return nil
}

func (s *sprintfBinding) DataChanged() {
	s.lock.Lock()
	s.lastErr = nil
	s.lock.Unlock()
	s.trigger()
}

func (s *sprintfBinding) getValues() ([]interface{}, error) {
	values := make([]interface{}, len(s.bindings))

	for i, b := range s.bindings {
		val, err := s.getValue(b)
		if err != nil {
			s.lastErr = err
			return nil, err
		}
		values[i] = val
	}

	return values, nil
}

func (s *sprintfBinding) getValue(item DataItem) (interface{}, error) {
	switch typed := item.(type) {
	case Bool:
		return typed.Get()
	case Bytes:
		return typed.Get()
	case Float:
		return typed.Get()
	case Int:
		return typed.Get()
	case Rune:
		return typed.Get()
	case String:
		return typed.Get()
	case URI:
		u, err := typed.Get()
		if err != nil {
			return nil, err
		}
		if u == nil {
			return "", nil
		}
		return u.String(), nil
	case Untyped:
		return typed.Get()
	default:
		return nil, errors.New("unsupported binding type")
	}
}

func (s *sprintfBinding) setBinding(item DataItem, value interface{}) error {
	switch typed := item.(type) {
	case Bool:
		if v, ok := value.(bool); ok {
			return typed.Set(v)
		}
		return errors.New("type mismatch for Bool binding")

	case Bytes:
		// Bytes cannot be round-tripped
		return errors.New("Bytes binding cannot be set from formatted string")

	case Float:
		switch v := value.(type) {
		case float64:
			return typed.Set(v)
		case float32:
			return typed.Set(float64(v))
		case int:
			return typed.Set(float64(v))
		}
		return errors.New("type mismatch for Float binding")

	case Int:
		if v, ok := value.(int); ok {
			return typed.Set(v)
		}
		return errors.New("type mismatch for Int binding")

	case Rune:
		if v, ok := value.(rune); ok {
			return typed.Set(v)
		}
		return errors.New("type mismatch for Rune binding")

	case String:
		if v, ok := value.(string); ok {
			return typed.Set(v)
		}
		return errors.New("type mismatch for String binding")

	case URI:
		if v, ok := value.(string); ok {
			uri, err := storage.ParseURI(v)
			if err != nil {
				return err
			}
			return typed.Set(uri)
		}
		return errors.New("type mismatch for URI binding")

	case Untyped:
		return typed.Set(value)

	default:
		return errors.New("unsupported binding type for Set")
	}
}

