		return typed.Get()
	case Rune:
		return typed.Get()
	case String:
		return typed.Get()
	case URI:
		u, err := typed.Get()
		if err != nil {
			return nil, err
		}
		if u == nil {
			return "", nil
		}
		return u.String(), nil
	case Untyped:
		return typed.Get()
	default:
		return nil, errors.New("unsupported binding type")
	}
}

func (s *sprintfBinding) setBinding(item DataItem, value interface{}) error {
	switch typed := item.(type) {
	case Bool:
		if v, ok := value.(bool); ok {
			return typed.Set(v)
		}
		return errors.New("type mismatch for Bool binding")

	case Bytes:
		// Bytes cannot be round-tripped
		return errors.New("Bytes binding cannot be set from formatted string")

	case Float:
		switch v := value.(type) {
		case float64:
			return typed.Set(v)
		case float32:
			return typed.Set(float64(v))
		case int:
			return typed.Set(float64(v))
		}
		return errors.New("type mismatch for Float binding")

	case Int:
		if v, ok := value.(int); ok {
			return typed.Set(v)
		}
		return errors.New("type mismatch for Int binding")

	case Rune:
		if v, ok := value.(rune); ok {
			return typed.Set(v)
		}
		return errors.New("type mismatch for Rune binding")

	case String:
		if v, ok := value.(string); ok {
			return typed.Set(v)
		}
		return errors.New("type mismatch for String binding")

	case URI:
		if v, ok := value.(string); ok {
			uri, err := storage.ParseURI(v)
			if err != nil {
				return err
			}
			return typed.Set(uri)
		}
		return errors.New("type mismatch for URI binding")

	case Untyped:
		return typed.Set(value)

	default:
		return errors.New("unsupported binding type for Set")
	}
}

